-- ============================================================
-- Update "Contacted" email template to include
-- 3 one-click demo slot booking CTAs ({{slots.*}} merge tags)
-- ============================================================

UPDATE sales_pipeline_email_templates SET
  subject   = 'Let''s show you Aliice, {{contact.first_name}} — pick a time that works 👇',

  body_html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Book Your Aliice Demo</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);max-width:600px;width:100%;"><tr><td style="background:#0ea5e9;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;"/><h1 style="margin:0;color:#0ea5e9;font-size:26px;font-weight:700;">See Aliice in action 🚀</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">Hi <strong>{{contact.first_name}}</strong> — ready to explore what Aliice can do for <strong>{{org.name}}</strong>?</p></td></tr><tr><td style="padding:8px 40px 32px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">We''d love to show you how clinics like yours use Aliice to automate bookings, billing, and patient management — all in one place. Pick a 30-minute slot that suits you:</p><!-- Slot 1 --><table cellpadding="0" cellspacing="0" width="100%" style="margin:0 0 12px;"><tr><td style="background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:12px;padding:0;overflow:hidden;"><a href="{{slots.slot1_url}}" style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;text-decoration:none;color:#0f172a;font-size:15px;font-weight:600;"><span style="display:inline-flex;align-items:center;gap:10px;"><span style="display:inline-block;width:32px;height:32px;background:#0ea5e9;border-radius:8px;text-align:center;line-height:32px;font-size:16px;">📅</span><span>{{slots.slot1_label}}</span></span><span style="background:#0ea5e9;color:#ffffff;font-size:13px;font-weight:700;padding:6px 16px;border-radius:8px;white-space:nowrap;">Book this slot →</span></a></td></tr></table><!-- Slot 2 --><table cellpadding="0" cellspacing="0" width="100%" style="margin:0 0 12px;"><tr><td style="background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:12px;padding:0;overflow:hidden;"><a href="{{slots.slot2_url}}" style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;text-decoration:none;color:#0f172a;font-size:15px;font-weight:600;"><span style="display:inline-flex;align-items:center;gap:10px;"><span style="display:inline-block;width:32px;height:32px;background:#0ea5e9;border-radius:8px;text-align:center;line-height:32px;font-size:16px;">📅</span><span>{{slots.slot2_label}}</span></span><span style="background:#0ea5e9;color:#ffffff;font-size:13px;font-weight:700;padding:6px 16px;border-radius:8px;white-space:nowrap;">Book this slot →</span></a></td></tr></table><!-- Slot 3 --><table cellpadding="0" cellspacing="0" width="100%" style="margin:0 0 28px;"><tr><td style="background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:12px;padding:0;overflow:hidden;"><a href="{{slots.slot3_url}}" style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;text-decoration:none;color:#0f172a;font-size:15px;font-weight:600;"><span style="display:inline-flex;align-items:center;gap:10px;"><span style="display:inline-block;width:32px;height:32px;background:#0ea5e9;border-radius:8px;text-align:center;line-height:32px;font-size:16px;">📅</span><span>{{slots.slot3_label}}</span></span><span style="background:#0ea5e9;color:#ffffff;font-size:13px;font-weight:700;padding:6px 16px;border-radius:8px;white-space:nowrap;">Book this slot →</span></a></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border-radius:12px;padding:20px;margin:0 0 8px;border:1px solid #e2e8f0;"><tr><td><p style="margin:0 0 12px;font-size:14px;font-weight:700;color:#475569;">✨ What we cover in 60 minutes</p><p style="margin:0 0 8px;font-size:14px;color:#475569;padding-bottom:8px;border-bottom:1px solid #e2e8f0;"><strong>📋 Full platform walkthrough</strong> — bookings, billing, patient records</p><p style="margin:0 0 8px;font-size:14px;color:#475569;padding-bottom:8px;border-bottom:1px solid #e2e8f0;"><strong>🎯 Tailored to {{org.name}}</strong> — we focus on your clinic''s needs</p><p style="margin:0 0 8px;font-size:14px;color:#475569;padding-bottom:8px;border-bottom:1px solid #e2e8f0;"><strong>💰 Transparent pricing</strong> — no surprises, no hard sell</p><p style="margin:0;font-size:14px;color:#475569;"><strong>❓ Open Q&amp;A</strong> — ask us anything</p></td></tr></table><p style="margin:16px 0 0;font-size:13px;color:#94a3b8;text-align:center;">None of these slots work? Reply to this email and we''ll find a time that does.</p></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;">Aliice · <a href="mailto:hello@aliice.app" style="color:#0ea5e9;text-decoration:none;">hello@aliice.app</a></p><p style="margin:6px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · All-in-one clinic management platform</p></td></tr></table></td></tr></table></body></html>',

  subject_fr = 'Découvrez Aliice, {{contact.first_name}} — choisissez un créneau 👇',

  body_html_fr = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Réservez votre démo Aliice</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);max-width:600px;width:100%;"><tr><td style="background:#0ea5e9;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;"/><h1 style="margin:0;color:#0ea5e9;font-size:26px;font-weight:700;">Voyez Aliice en action 🚀</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">Bonjour <strong>{{contact.first_name}}</strong> — prêt(e) à découvrir ce qu''Aliice peut faire pour <strong>{{org.name}}</strong> ?</p></td></tr><tr><td style="padding:8px 40px 32px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">Nous aimerions vous montrer comment des cliniques comme la vôtre utilisent Aliice pour automatiser les réservations, la facturation et la gestion des patients. Choisissez un créneau de 60 minutes :</p><!-- Créneau 1 --><table cellpadding="0" cellspacing="0" width="100%" style="margin:0 0 12px;"><tr><td style="background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:12px;padding:0;overflow:hidden;"><a href="{{slots.slot1_url}}" style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;text-decoration:none;color:#0f172a;font-size:15px;font-weight:600;"><span style="display:inline-flex;align-items:center;gap:10px;"><span style="display:inline-block;width:32px;height:32px;background:#0ea5e9;border-radius:8px;text-align:center;line-height:32px;font-size:16px;">📅</span><span>{{slots.slot1_label}}</span></span><span style="background:#0ea5e9;color:#ffffff;font-size:13px;font-weight:700;padding:6px 16px;border-radius:8px;white-space:nowrap;">Réserver →</span></a></td></tr></table><!-- Créneau 2 --><table cellpadding="0" cellspacing="0" width="100%" style="margin:0 0 12px;"><tr><td style="background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:12px;padding:0;overflow:hidden;"><a href="{{slots.slot2_url}}" style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;text-decoration:none;color:#0f172a;font-size:15px;font-weight:600;"><span style="display:inline-flex;align-items:center;gap:10px;"><span style="display:inline-block;width:32px;height:32px;background:#0ea5e9;border-radius:8px;text-align:center;line-height:32px;font-size:16px;">📅</span><span>{{slots.slot2_label}}</span></span><span style="background:#0ea5e9;color:#ffffff;font-size:13px;font-weight:700;padding:6px 16px;border-radius:8px;white-space:nowrap;">Réserver →</span></a></td></tr></table><!-- Créneau 3 --><table cellpadding="0" cellspacing="0" width="100%" style="margin:0 0 28px;"><tr><td style="background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:12px;padding:0;overflow:hidden;"><a href="{{slots.slot3_url}}" style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;text-decoration:none;color:#0f172a;font-size:15px;font-weight:600;"><span style="display:inline-flex;align-items:center;gap:10px;"><span style="display:inline-block;width:32px;height:32px;background:#0ea5e9;border-radius:8px;text-align:center;line-height:32px;font-size:16px;">📅</span><span>{{slots.slot3_label}}</span></span><span style="background:#0ea5e9;color:#ffffff;font-size:13px;font-weight:700;padding:6px 16px;border-radius:8px;white-space:nowrap;">Réserver →</span></a></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border-radius:12px;padding:20px;margin:0 0 8px;border:1px solid #e2e8f0;"><tr><td><p style="margin:0 0 12px;font-size:14px;font-weight:700;color:#475569;">✨ Ce que nous allons couvrir en 60 minutes</p><p style="margin:0 0 8px;font-size:14px;color:#475569;padding-bottom:8px;border-bottom:1px solid #e2e8f0;"><strong>📋 Présentation complète</strong> — réservations, facturation, dossiers patients</p><p style="margin:0 0 8px;font-size:14px;color:#475569;padding-bottom:8px;border-bottom:1px solid #e2e8f0;"><strong>🎯 Adapté à {{org.name}}</strong> — nous nous concentrons sur vos besoins</p><p style="margin:0 0 8px;font-size:14px;color:#475569;padding-bottom:8px;border-bottom:1px solid #e2e8f0;"><strong>💰 Tarifs transparents</strong> — aucune surprise, aucune pression</p><p style="margin:0;font-size:14px;color:#475569;"><strong>❓ Questions libres</strong> — posez-nous tout</p></td></tr></table><p style="margin:16px 0 0;font-size:13px;color:#94a3b8;text-align:center;">Aucun de ces créneaux ne vous convient ? Répondez à cet e-mail et nous trouverons un moment ensemble.</p></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;">Aliice · <a href="mailto:hello@aliice.app" style="color:#0ea5e9;text-decoration:none;">hello@aliice.app</a></p><p style="margin:6px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · Plateforme tout-en-un pour cliniques</p></td></tr></table></td></tr></table></body></html>'

WHERE name = 'Follow-up – We''d Love to Connect';
